import React,{useEffect,useMemo,useState} from 'react';
import {Alert,KeyboardAvoidingView,Modal,Platform,Pressable,SafeAreaView,ScrollView,StatusBar,StyleSheet,Text,TextInput,View} from 'react-native';
import {AppProvider,useApp} from './src/context/AppContext';
import Ionicons from '@expo/vector-icons/Ionicons';
import {providers,services} from './src/data/mockData';
import {CancellationReason,Coordinates,Message,Provider,Request,Review,Role} from './src/types';
import {distanceInKm,formatDistance,getCurrentLocation} from './src/services/location';

const C={ink:'#16232D',muted:'#6B7785',line:'#E7ECF0',bg:'#F7FAFC',brand:'#087F70',brandDark:'#075A51',soft:'#E4F5F0',gold:'#F4B740',white:'#FFFFFF'};
const serviceName=(trade:string)=>trade.replace(' specialist','').replace('Certified ','').replace('Home ','');
const tabIconName=(name:string)=>({Home:'home-outline',Bookings:'calendar-outline',Messages:'chatbubble-ellipses-outline',Profile:'person-outline',Complaints:'alert-circle-outline'}[name]||'ellipse-outline') as any;

function Header({title,subtitle}:{title:string;subtitle?:string}){const {messages,requests,complaints,role}=useApp();const [open,setOpen]=useState(false);const items=[...messages.filter(m=>m.unread).map(m=>({icon:'chatbubble-ellipses-outline',title:'New message',text:`${m.provider}: ${m.text}`})),...(role==='provider'||role==='administrator'?requests.filter(r=>r.status==='Pending').map(r=>({icon:'briefcase-outline',title:'Pending job',text:`${r.service} request from ${r.customer||'customer'}`})):[]),...(role==='administrator'?complaints.filter(c=>c.status==='Open').map(c=>({icon:'alert-circle-outline',title:'Open complaint',text:c.subject})):[])];return <><View style={s.header}><View style={{flex:1}}><Text style={s.h1}>{title}</Text>{subtitle&&<Text style={s.subtitle}>{subtitle}</Text>}</View><Pressable style={s.iconButton} onPress={()=>setOpen(true)} accessibilityRole="button" accessibilityLabel="Open notifications"><Ionicons name="notifications-outline" size={20} color={C.ink}/>{items.length>0&&<View style={s.notificationDot}/>}</Pressable></View><Modal visible={open} transparent animationType="fade" onRequestClose={()=>setOpen(false)}><View style={s.overlay}><View style={[s.sheet,{maxHeight:'75%'}]}><View style={s.row}><Text style={s.modalTitle}>Notifications</Text><Pressable onPress={()=>setOpen(false)}><Text style={{fontSize:23}}>×</Text></Pressable></View>{items.length===0?<Empty icon="✅" title="You’re all caught up" text="There are no new notifications."/>:items.slice(0,8).map((item,index)=><View style={s.notificationItem} key={`${item.title}-${index}`}><Ionicons name={item.icon as any} size={21} color={C.brand}/><View style={{flex:1,marginLeft:12}}><Text style={s.cardTitle}>{item.title}</Text><Text style={s.muted} numberOfLines={2}>{item.text}</Text></View></View>)}</View></View></Modal></>}
function ProviderDashboard(){const {requests,availability,setAvailability,profile,providerDirectory}=useApp();const provider=providerDirectory.find(p=>p.name===profile.name)||providerDirectory[0];const myRequests=requests.filter(r=>r.provider===provider.name||r.status==='Pending');const online=availability[provider.id]!==false;const active=myRequests.filter(r=>r.status==='Pending'||r.status==='Accepted'||r.status==='In progress').length;const completed=myRequests.filter(r=>r.status==='Completed').length;return <ScrollView style={s.page} contentContainerStyle={s.content}><Header title="Provider dashboard" subtitle="Run your local services business"/><View style={[s.onlineCard,{backgroundColor:online?C.brandDark:'#5E6870'}]}><View style={{flex:1}}><Text style={s.onlineEyebrow}>{online?'YOU ARE ONLINE':'YOU ARE OFFLINE'}</Text><Text style={s.onlineTitle}>{online?'Ready for new jobs':'Turn on to receive jobs'}</Text><Text style={s.onlineCopy}>{online?'Customers nearby can now request your services.':'You will not receive new requests while offline.'}</Text></View><Pressable style={s.onlineToggle} onPress={()=>setAvailability(provider.id,!online)}><View style={[s.toggleKnob,{alignSelf:online?'flex-end':'flex-start'}]}/></Pressable></View><View style={s.adminGrid}><AdminStat value={String(active)} label="Active jobs" icon="📋"/><AdminStat value={String(completed)} label="Completed" icon="✓"/><AdminStat value="4.9" label="Your rating" icon="★"/><AdminStat value="R2,850" label="This month" icon="💰"/></View><Text style={s.sectionTitle}>Today’s checklist</Text><View style={s.adminCard}><Checklist label="Availability is on" done={online}/><Checklist label="Profile is verified" done/><Checklist label="Service area added" done/><Checklist label="Payment details added" done={false}/></View><Text style={s.sectionTitle}>Next job</Text>{myRequests.find(r=>r.status==='Accepted'||r.status==='In progress')?<View style={s.booking}><Text style={s.cardTitle}>{myRequests.find(r=>r.status==='Accepted'||r.status==='In progress')?.service}</Text><Text style={s.muted}>Today · {myRequests.find(r=>r.status==='Accepted'||r.status==='In progress')?.time}</Text><Text style={s.detail}>📍 {myRequests.find(r=>r.status==='Accepted'||r.status==='In progress')?.address}</Text></View>:<Empty icon="🛠️" title="No upcoming jobs" text="Keep your availability on to receive local requests."/>}</ScrollView>}
function Checklist({label,done}:{label:string;done:boolean}){return <View style={s.checklist}><Text style={[s.checkIcon,{color:done?C.brand:C.muted}]}>{done?'✓':'○'}</Text><Text style={done?s.cardTitle:s.muted}>{label}</Text><Text style={s.chevron}>›</Text></View>}
function SystemAdminDashboard(){const {requests,reviews,providerStatuses,availability,setProviderStatus,setAvailability,providerDirectory,addProvider,serviceDirectory,addService}=useApp();const totalUsers=providerDirectory.length+1;const approved=Object.values(providerStatuses).filter(v=>v==='approved').length;const online=Object.values(availability).filter(Boolean).length;const [onboardOpen,setOnboardOpen]=useState(false);const [providerName,setProviderName]=useState('');const [providerTrade,setProviderTrade]=useState('');const [serviceOpen,setServiceOpen]=useState(false);const [newServiceName,setNewServiceName]=useState('');const [newServiceDescription,setNewServiceDescription]=useState('');const [newServiceIcon,setNewServiceIcon]=useState('🛠️');const [providerIcon,setProviderIcon]=useState('🛠️');const [providerService,setProviderService]=useState(serviceDirectory[0]?.name||'');const configureService=()=>{if(!newServiceName.trim()){Alert.alert('Complete the service','Add a service name first.');return;}addService({id:'service-'+Date.now(),name:newServiceName.trim(),icon:newServiceIcon,color:'#E5E9FF',description:newServiceDescription.trim()||'Trusted local service'});setNewServiceName('');setNewServiceDescription('');setServiceOpen(false);};const onboard=()=>{if(!providerName.trim()||!providerService.trim()){Alert.alert('Complete the profile','Add a provider name and trade first.');return;}const id='p'+Date.now();addProvider({id,name:providerName.trim(),trade:providerService.trim(),rating:0,reviews:0,distance:'Distance unavailable',price:'From R250',avatar:providerIcon,verified:false,bio:'New FixMate provider awaiting verification.'});setProviderStatus(id,'pending');setAvailability(id,false);setProviderName('');setProviderTrade('');setProviderService(serviceDirectory[0]?.name||'');setOnboardOpen(false);Alert.alert('Provider onboarded','The provider was added as pending and is ready for review.');};return <ScrollView style={s.page} contentContainerStyle={s.content}><Header title="System admin" subtitle="Platform operations and system governance"/><View style={[s.systemBanner]}><Text style={{fontSize:26}}>🛡️</Text><View style={{flex:1,marginLeft:12}}><Text style={s.cardTitle}>System status: healthy</Text><Text style={s.muted}>All FixMate services are operating normally.</Text></View><View style={s.healthDot}/></View><View style={s.adminGrid}><AdminStat value={String(totalUsers)} label="Accounts" icon="👥"/><AdminStat value={String(approved)} label="Approved pros" icon="✓"/><AdminStat value={String(online)} label="Online now" icon="●"/><AdminStat value={String(requests.length)} label="Requests" icon="📋"/></View><Pressable style={s.button} onPress={()=>setOnboardOpen(true)}><Text style={s.buttonText}>＋ Onboard provider</Text></Pressable><Text style={s.sectionTitle}>Provider directory</Text><View style={s.adminCard}>{providerDirectory.map(p=><View style={s.activity} key={p.id}><Text style={{fontSize:22}}>{p.avatar}</Text><View style={{flex:1,marginLeft:10}}><Text style={s.cardTitle}>{p.name}</Text><Text style={s.muted}>{p.trade}</Text></View><Text style={s.adminStatus}>{providerStatuses[p.id]||'pending'}</Text></View>)}</View><View style={s.row}><Text style={s.sectionTitle}>Services</Text><Pressable onPress={()=>setServiceOpen(true)}><Text style={s.seeAll}>＋ Configure</Text></Pressable></View><View style={s.adminCard}>{serviceDirectory.map(sv=><View style={s.activity} key={sv.id}><Text style={{fontSize:22}}>{sv.icon}</Text><View style={{flex:1,marginLeft:10}}><Text style={s.cardTitle}>{sv.name}</Text><Text style={s.muted}>{sv.description}</Text></View></View>)}</View><Text style={s.sectionTitle}>Access control</Text><View style={s.adminCard}><AccessRow role="Customer" count="Public marketplace access" color={C.brand}/><AccessRow role="Service provider" count={approved+' approved accounts'} color={C.gold}/><AccessRow role="Administrator" count="Marketplace moderation" color="#7D6ACB"/><AccessRow role="System admin" count="Full platform access" color="#C65C5C"/></View><Text style={s.sectionTitle}>System activity</Text>{[{label:'Bookings processed',value:String(requests.length),icon:'📋'},{label:'Reviews stored',value:String(reviews.length),icon:'★'},{label:'Provider approvals',value:String(approved),icon:'✓'},{label:'Availability signals',value:String(online),icon:'⌁'}].map(item=><View style={s.activity} key={item.label}><Text style={{fontSize:18}}>{item.icon}</Text><Text style={[s.cardTitle,{flex:1,marginLeft:10}]}>{item.label}</Text><Text style={s.adminStatus}>{item.value}</Text></View>)}<Text style={s.sectionTitle}>Danger zone</Text><View style={s.adminCard}><Text style={s.cardTitle}>System-wide controls</Text><Text style={s.muted}>Use these controls carefully. In production they should require authentication and audit logging.</Text><Pressable style={s.outlineButton} onPress={()=>Alert.alert('Maintenance mode','Maintenance mode would be enabled for all users after confirmation.')}><Text style={s.outlineText}>Configure maintenance mode</Text></Pressable><Pressable style={s.outlineButton} onPress={()=>Alert.alert('Audit export','An audit log export would be generated and downloaded.')}><Text style={s.outlineText}>Export audit log</Text></Pressable></View><Modal visible={onboardOpen} transparent animationType="slide" onRequestClose={()=>setOnboardOpen(false)}><View style={s.overlay}><View style={s.sheet}><View style={s.row}><Text style={s.modalTitle}>Onboard provider</Text><Pressable onPress={()=>setOnboardOpen(false)}><Text style={{fontSize:23}}>×</Text></Pressable></View><TextInput value={providerName} onChangeText={setProviderName} placeholder="Provider or business name" style={[s.input,{marginTop:18}]}/><Text style={s.modalLabel}>Service offered</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.horizontalGap}>{serviceDirectory.map(sv=><Pressable key={sv.id} onPress={()=>{setProviderService(sv.name);setProviderTrade(sv.name)}} style={[s.quickService,{borderColor:providerService===sv.name?C.brand:C.line,backgroundColor:providerService===sv.name?C.soft:C.white}]}><Text style={{fontSize:22}}>{sv.icon}</Text><Text style={s.cardTitle}>{sv.name}</Text></Pressable>)}</ScrollView><Text style={s.modalLabel}>Choose provider icon</Text><View style={s.iconPicker}>{['🛠️','🔧','⚡','✨','🎨','🌿','🏠','🚚'].map(icon=><Pressable key={icon} onPress={()=>setProviderIcon(icon)} style={[s.iconChoice,providerIcon===icon&&s.iconChoiceActive]}><Text style={{fontSize:25}}>{icon}</Text></Pressable>)}</View><Pressable style={s.button} onPress={onboard}><Text style={s.buttonText}>Add provider for approval</Text></Pressable></View></View></Modal><Modal visible={serviceOpen} transparent animationType="slide" onRequestClose={()=>setServiceOpen(false)}><View style={s.overlay}><View style={s.sheet}><View style={s.row}><Text style={s.modalTitle}>Configure service</Text><Pressable onPress={()=>setServiceOpen(false)}><Text style={{fontSize:23}}>×</Text></Pressable></View><TextInput value={newServiceName} onChangeText={setNewServiceName} placeholder="Service name" style={[s.input,{marginTop:18}]}/><TextInput value={newServiceDescription} onChangeText={setNewServiceDescription} placeholder="Short description" style={s.input}/><Text style={s.modalLabel}>Choose icon</Text><View style={s.iconPicker}>{['🛠️','🔧','⚡','✨','🎨','🌿','🏠','🚚'].map(icon=><Pressable key={icon} onPress={()=>setNewServiceIcon(icon)} style={[s.iconChoice,newServiceIcon===icon&&s.iconChoiceActive]}><Text style={{fontSize:25}}>{icon}</Text></Pressable>)}</View><Pressable style={s.button} onPress={configureService}><Text style={s.buttonText}>Save service</Text></Pressable></View></View></Modal></ScrollView>}
function AccessRow({role,count,color}:{role:string;count:string;color:string}){return <View style={s.accessRow}><View style={[s.accessDot,{backgroundColor:color}]}/><View style={{flex:1}}><Text style={s.cardTitle}>{role}</Text><Text style={s.muted}>{count}</Text></View><Text style={s.chevron}>›</Text></View>}
function Home({openProvider,openQuickMatch}:{openProvider:(p:Provider)=>void;openQuickMatch:()=>void}){const {providerStatuses,availability,profile,updateProfile,providerDirectory,serviceDirectory}=useApp();const [query,setQuery]=useState('');const [searchFocused,setSearchFocused]=useState(false);const [category,setCategory]=useState('');const [location,setLocation]=useState(profile.address||'Cape Town City Bowl');const [locationOpen,setLocationOpen]=useState(false);const [locationBusy,setLocationBusy]=useState(false);const useCurrentLocation=async()=>{setLocationBusy(true);const coordinates=await getCurrentLocation();if(coordinates){setLocation('Current location');updateProfile({coordinates,address:'Current location'});}else Alert.alert('Location unavailable','Please allow location access in your browser or device settings.');setLocationBusy(false);return Boolean(coordinates);};const filtered=useMemo(()=>{const term=query.trim().toLowerCase().replace(/\b(i|need|help|with|a|my|please|find|get|for|me|want|someone)\b/g,' ').replace(/\s+/g,' ').trim();return providerDirectory.filter(p=>{const eligible=providerStatuses[p.id]==='approved'&&availability[p.id]!==false;const service=serviceDirectory.find(x=>p.trade.toLowerCase().includes(x.name.toLowerCase()));const haystack=`${p.name} ${p.trade} ${service?.name||''} ${service?.description||''}`.toLowerCase();return eligible&&(!category||haystack.includes(category))&&(!term||term.split(' ').filter(Boolean).every(word=>haystack.includes(word)));});},[query,category,providerStatuses,availability,providerDirectory,serviceDirectory]);return <><ScrollView style={s.page} contentContainerStyle={s.content} keyboardShouldPersistTaps="handled"><Header title="Good morning, Alex 👋" subtitle="Trusted help, right in your neighbourhood"/><Pressable style={s.location} accessibilityRole="button" accessibilityLabel="Change service location" onPress={()=>setLocationOpen(true)}><Ionicons name="location-outline" size={20} color={C.brand}/><View style={{flex:1}}><Text style={s.locationLabel}>Your location</Text><Text style={s.locationValue}>{location}</Text></View><Text style={s.chevron}>›</Text></Pressable><View style={s.search}><Ionicons name="search-outline" size={22} color={C.brand}/><TextInput value={query} onChangeText={text=>{setQuery(text);setCategory('')}} placeholder={searchFocused?'':'What do you need help with?'} placeholderTextColor={C.muted} style={s.searchInput} onFocus={()=>setSearchFocused(true)} onBlur={()=>setSearchFocused(false)} onSubmitEditing={()=>{const match=serviceDirectory.find(x=>`${x.name} ${x.description}`.toLowerCase().includes(query.toLowerCase()));if(match)setCategory(match.name.toLowerCase());}}/>{query&&<Pressable onPress={()=>setQuery('')}><Text style={s.clear}>×</Text></Pressable>}</View><View style={s.row}><Text style={s.sectionTitle}>What can we help with?</Text><Text style={s.seeAll}>See all</Text></View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.horizontalGap}>{serviceDirectory.map(x=><Pressable key={x.id} onPress={()=>setCategory(category===x.name.toLowerCase()?'':x.name.toLowerCase())} style={[s.service,{backgroundColor:x.color,borderColor:category===x.name.toLowerCase()?C.brand:x.color}]}><Text style={{fontSize:27}}>{x.icon}</Text><Text style={s.serviceName}>{x.name}</Text><Text style={s.serviceDescription}>{x.description.split(',')[0]}</Text></Pressable>)}</ScrollView><View style={s.hero}><View style={{flex:1}}><Text style={s.heroEyebrow}>FIXMATE PROMISE</Text><Text style={s.heroTitle}>Small jobs. Big peace of mind.</Text><Text style={s.heroCopy}>Verified local pros, transparent pricing and support when you need it.</Text><Pressable onPress={openQuickMatch}><Text style={s.heroLink}>Request a pro now  →</Text></Pressable></View><Text style={s.heroEmoji}>🧰</Text></View><View style={s.trustRow}><Trust icon="✓" text="Verified pros"/><Trust icon="★" text="Real reviews"/><Trust icon="⌁" text="Secure booking"/></View><View style={[s.row,{marginTop:26}]}><View><Text style={s.sectionTitle}>Recommended for you</Text><Text style={s.sectionHint}>{filtered.length} trusted professionals nearby</Text></View><Text style={s.seeAll}>Sort ▾</Text></View>{filtered.length===0?<Empty icon="🔎" title="No pros found" text="Try another service or search term."/>:filtered.map(p=><ProviderCard key={p.id} provider={p} userCoordinates={profile.coordinates} onPress={()=>openProvider(p)}/>)}</ScrollView><Modal visible={locationOpen} transparent animationType="slide" onRequestClose={()=>setLocationOpen(false)}><View style={s.overlay}><View style={s.sheet}><View style={s.row}><Text style={s.modalTitle}>Choose your location</Text><Pressable onPress={()=>setLocationOpen(false)}><Text style={{fontSize:23}}>×</Text></Pressable></View><Text style={[s.muted,{marginTop:6}]}>We’ll show service providers near this area.</Text>{['Cape Town City Bowl','Sea Point','Woodstock','Use current location'].map(option=><Pressable key={option} style={s.menu} onPress={async()=>{if(option==='Use current location'){const found=await useCurrentLocation();if(found)setLocationOpen(false);}else{setLocation(option);updateProfile({address:option,coordinates:undefined});setLocationOpen(false);}}}><View style={{flexDirection:'row',alignItems:'center',gap:12}}><Ionicons name={option==='Use current location'?'locate-outline':'location-outline'} size={20} color={C.brand}/><Text style={s.cardTitle}>{option==='Use current location'&&locationBusy?'Locating…':option}</Text></View><Text style={s.chevron}>{location===option?'✓':'›'}</Text></Pressable>)}<Pressable style={s.button} onPress={()=>setLocationOpen(false)}><Text style={s.buttonText}>Done</Text></Pressable></View></View></Modal></>}

function Trust({icon,text}:{icon:string;text:string}){return <View style={s.trust}><View style={s.trustIcon}><Text style={{color:C.brand,fontWeight:'800'}}>{icon}</Text></View><Text style={s.trustText}>{text}</Text></View>}
function ProviderCard({provider,userCoordinates,onPress}:{provider:Provider;userCoordinates?:Coordinates;onPress:()=>void}){const {favourites,toggleFavourite}=useApp();return <Pressable style={({pressed})=>[s.card,pressed&&{opacity:.8}]} onPress={onPress}><View style={s.avatar}><Text style={s.avatarText}>{provider.avatar}</Text></View><View style={{flex:1}}><View style={s.row}><View style={{flex:1}}><View style={s.nameLine}><Text style={s.cardTitle}>{provider.name}</Text>{provider.verified&&<View style={s.verified}><Text style={{fontSize:10,color:C.brand}}>✓</Text><Text style={s.verifiedText}>Verified</Text></View>}</View><Text style={s.muted}>{provider.trade}</Text></View><Pressable onPress={()=>toggleFavourite(provider.id)} hitSlop={12}><Text style={s.heart}>{favourites.includes(provider.id)?'♥':'♡'}</Text></Pressable></View><View style={s.cardMeta}><Text style={s.rating}>★ {provider.rating}</Text><Text style={s.metaText}>{provider.reviews} reviews</Text><Text style={s.metaText}>• {formatDistance(distanceInKm(userCoordinates||{latitude:-33.9249,longitude:18.4241},provider.coordinates))}</Text><Text style={s.cardPrice}>{provider.price}</Text></View></View></Pressable>}

function Requests({onReview,onTrack}:{onReview:(r:Request)=>void;onTrack:(r:Request)=>void}){const {requests,role,updateRequest,canCancelRequest,cancelRequest,hasReview,profile}=useApp();const canManageJobs=role==='provider'||role==='administrator';const visibleRequests=role==='provider'?requests.filter(r=>r.provider===profile.name||r.status==='Pending'):requests;const [filter,setFilter]=useState<'All'|'Upcoming'|'Completed'>('All');const [cancelTarget,setCancelTarget]=useState<Request|null>(null);const [cancelReason,setCancelReason]=useState<CancellationReason>('Changed my mind');const shown=visibleRequests.filter(r=>filter==='All'||(filter==='Completed'?r.status==='Completed':r.status!=='Completed'&&r.status!=='Cancelled'));const nextStatus=(r:Request)=>r.status==='Pending'?'Accepted':r.status==='Accepted'?'In progress':'Completed';const reasons:CancellationReason[]=['Changed my mind','Found another provider','Provider is delayed','Provider requested cancellation','Emergency','Other'];const requestCancellation=(r:Request)=>{setCancelReason(role==='provider'?'Provider requested cancellation':'Changed my mind');setCancelTarget(r);};const confirmCancellation=()=>{if(!cancelTarget)return;cancelRequest(cancelTarget.id,cancelReason);setCancelTarget(null);};return <><ScrollView style={s.page} contentContainerStyle={s.content}><Header title={role==='provider'?'Your job board':'Your bookings'} subtitle={role==='provider'?'Manage work and grow your business':'Everything you have booked, in one place'}/><View style={s.filterRow}>{(['All','Upcoming','Completed'] as const).map(x=><Pressable key={x} onPress={()=>setFilter(x)}><Text style={filter===x?s.filterActive:s.filter}>{x}</Text></Pressable>)}</View>{shown.length===0?<Empty icon="📋" title={filter==='Completed'?'No completed jobs':'No bookings yet'} text="Your service activity will appear here."/>:shown.map(r=><View style={s.booking} key={r.id}><View style={s.row}><View style={s.bookingIcon}><Text>{r.status==='Completed'?'✓':r.status==='Searching'?'🔎':'🔧'}</Text></View><View style={{flex:1,marginLeft:12}}><Text style={s.cardTitle}>{r.service}</Text><Text style={s.muted}>{role==='provider'?'For '+(r.customer||'customer'):r.provider}</Text></View><Text style={[s.pill,{color:r.status==='Completed'?C.brand:r.status==='Cancelled'?'#C65C5C':r.status==='Searching'?C.brand:C.gold}]}>{r.status}</Text></View><View style={s.detailGrid}><Text style={s.detail}>📅  {r.date}</Text><Text style={s.detail}>⏰  {r.time}</Text><Text style={s.detail}>📍  {r.address}</Text><Text style={s.detail}>💳  {r.price}</Text></View>{canManageJobs&&(r.status==='Pending'||r.status==='Accepted'||r.status==='In progress')&&<Pressable style={s.buttonSmall} onPress={()=>updateRequest(r.id,nextStatus(r))}><Text style={s.buttonText}>{r.status==='Pending'?'Accept this job':r.status==='Accepted'?'Start job':'Mark completed'}</Text></Pressable>}{canCancelRequest(r)&&<Pressable style={s.outlineButton} onPress={()=>requestCancellation(r)}><Text style={s.outlineText}>{role==='provider'?'Cancel job':'Cancel booking'}</Text></Pressable>}{role==='customer'&&(r.status==='Accepted'||r.status==='In progress')&&<Pressable style={s.trackButton} onPress={()=>onTrack(r)}><Text style={s.trackText}>⌁  Track your provider</Text></Pressable>}{role==='customer'&&r.status==='Completed'&&!hasReview(r.id)&&<Pressable style={s.buttonSmall} onPress={()=>onReview(r)}><Text style={s.buttonText}>Rate your experience</Text></Pressable>}</View>)}</ScrollView><Modal visible={Boolean(cancelTarget)} transparent animationType="slide" onRequestClose={()=>setCancelTarget(null)}><View style={s.overlay}><View style={s.sheet}><View style={s.row}><View><Text style={s.modalTitle}>Cancel {role==='provider'?'job':'booking'}?</Text><Text style={s.muted}>{cancelTarget?.status==='Accepted'&&role==='customer'?'A R50 mock cancellation fee applies.':'This action will notify the other party.'}</Text></View><Pressable onPress={()=>setCancelTarget(null)}><Text style={{fontSize:23}}>×</Text></Pressable></View><Text style={s.modalLabel}>Why are you cancelling?</Text>{reasons.map(reason=><Pressable key={reason} style={[s.menu,{borderBottomWidth:1,borderBottomColor:C.line,backgroundColor:cancelReason===reason?C.soft:C.white}]} onPress={()=>setCancelReason(reason)}><Text style={s.cardTitle}>{reason}</Text><Text style={cancelReason===reason?s.settingOn:s.chevron}>{cancelReason===reason?'✓':'›'}</Text></Pressable>)}<Pressable style={s.button} onPress={confirmCancellation}><Text style={s.buttonText}>Confirm cancellation</Text></Pressable><Pressable style={s.outlineButton} onPress={()=>setCancelTarget(null)}><Text style={s.outlineText}>Keep booking</Text></Pressable></View></View></Modal></>}
function Messages({openMessage}:{openMessage:(m:Message)=>void}){const {messages}=useApp();return <ScrollView style={s.page} contentContainerStyle={s.content}><Header title="Messages" subtitle="Chat directly with your service pros"/>{messages.map(m=><Pressable style={s.message} key={m.id} onPress={()=>openMessage(m)}><View style={s.avatar}><Text style={s.avatarText}>{m.avatar}</Text></View><View style={{flex:1}}><View style={s.row}><Text style={s.cardTitle}>{m.provider}</Text><Text style={s.muted}>{m.timestamp}</Text></View><Text style={s.muted} numberOfLines={2}>{m.text}</Text><Text style={s.messageStatus}>Open conversation · Reply ›</Text></View>{m.unread&&<View style={s.dot}/>}</Pressable>)}{messages.length===0&&<Empty icon="💬" title="Your conversations are private" text="Chat with a provider after you book a service."/>}</ScrollView>}
function AdminDashboard({openComplaint}:{openComplaint:(r:Request)=>void}){const {requests,reviews,providerStatuses,setProviderStatus,setAvailability,providerDirectory}=useApp();const pending=providerDirectory.filter(p=>providerStatuses[p.id]==='pending');const approved=providerDirectory.filter(p=>providerStatuses[p.id]==='approved');return <ScrollView style={s.page} contentContainerStyle={s.content}><Header title="Admin console" subtitle="Keep the FixMate marketplace safe and healthy"/><View style={s.adminGrid}><AdminStat value={String(requests.length)} label="Total bookings" icon="📋"/><AdminStat value={String(approved.length)} label="Approved pros" icon="✓"/><AdminStat value={String(pending.length)} label="Needs review" icon="⚠️"/><AdminStat value={String(reviews.length)} label="Reviews" icon="★"/></View><Text style={s.sectionTitle}>Provider approvals</Text>{pending.length===0?<Empty icon="✅" title="All caught up" text="There are no provider applications waiting for review."/>:pending.map(p=><View style={s.adminCard} key={p.id}><View style={s.row}><View style={s.avatar}><Text style={s.avatarText}>{p.avatar}</Text></View><View style={{flex:1,marginLeft:12}}><Text style={s.cardTitle}>{p.name}</Text><Text style={s.muted}>{p.trade}</Text><Text style={s.muted}>{p.bio}</Text></View></View><View style={s.adminActions}><Pressable style={s.buttonSmall} onPress={()=>{setProviderStatus(p.id,'approved');setAvailability(p.id,true);Alert.alert('Provider approved',p.name+' can now receive bookings.')}}><Text style={s.buttonText}>Approve</Text></Pressable><Pressable style={s.outlineButton} onPress={()=>setProviderStatus(p.id,'suspended')}><Text style={s.outlineText}>Decline</Text></Pressable></View></View>)}<Text style={s.sectionTitle}>Recent activity</Text>{requests.slice(0,5).map(r=><View style={s.activity} key={r.id}><Text style={{fontSize:18}}>🔧</Text><View style={{flex:1,marginLeft:10}}><Text style={s.cardTitle}>{r.service} · {r.status}</Text><Text style={s.muted}>{r.provider} · {r.date}</Text></View><Text style={s.adminStatus}>{r.price}</Text><Pressable onPress={()=>openComplaint(r)}><Text style={s.settingOff}>Complaint</Text></Pressable></View>)}<Text style={s.sectionTitle}>Account controls</Text><View style={s.adminCard}><Text style={s.cardTitle}>Marketplace mode</Text><Text style={s.muted}>Provider approvals are persisted locally and ready to be moved to an admin-only Firestore collection.</Text>{approved.slice(0,3).map(p=><View style={s.row} key={p.id}><Text style={s.muted}>{p.name}</Text><Pressable onPress={()=>setProviderStatus(p.id,'suspended')}><Text style={s.settingOff}>Suspend</Text></Pressable></View>)}</View></ScrollView>}
function AdminStat({value,label,icon}:{value:string;label:string;icon:string}){return <View style={s.adminStat}><Text style={{fontSize:20}}>{icon}</Text><Text style={s.adminValue}>{value}</Text><Text style={s.adminLabel}>{label}</Text></View>}
function Profile(){const {role,setRole,profile,updateProfile,favourites,logout,providerDirectory}=useApp();const [editing,setEditing]=useState(false);const [name,setName]=useState(profile.name);const [address,setAddress]=useState(profile.address);const save=()=>{updateProfile({name,address});setEditing(false);};return <ScrollView style={s.page} contentContainerStyle={s.content}><Header title={role==='administrator'?'Admin profile':'Profile'} subtitle="Manage your FixMate account"/><View style={s.profile}><View style={[s.avatar,{width:74,height:74,borderRadius:37}]}><Text style={{fontSize:25,fontWeight:'800',color:C.brand}}>{profile.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</Text></View><Text style={[s.cardTitle,{fontSize:21,marginTop:12}]}>{profile.name}</Text><Text style={s.muted}>{profile.email}</Text><View style={s.profileBadge}><Text style={{color:C.brand}}>✓</Text><Text style={s.verifiedText}>Member since 2024</Text></View></View><Text style={s.sectionTitle}>Choose your role</Text><View style={s.roleList}><Pressable style={[s.roleOption,role==='customer'&&s.switchOn]} onPress={()=>setRole('customer')}><Text style={s.roleEmoji}>🏠</Text><View style={{flex:1}}><Text style={s.cardTitle}>Customer</Text><Text style={s.muted}>Find and book local services</Text></View><Text style={role==='customer'?s.settingOn:s.chevron}>{role==='customer'?'✓':'›'}</Text></Pressable><Pressable style={[s.roleOption,role==='provider'&&s.switchOn]} onPress={()=>setRole('provider')}><Text style={s.roleEmoji}>🛠️</Text><View style={{flex:1}}><Text style={s.cardTitle}>Service provider</Text><Text style={s.muted}>Manage jobs and grow your business</Text></View><Text style={role==='provider'?s.settingOn:s.chevron}>{role==='provider'?'✓':'›'}</Text></Pressable><Pressable style={[s.roleOption,role==='administrator'&&s.switchOn]} onPress={()=>setRole('administrator')}><Text style={s.roleEmoji}>🛡️</Text><View style={{flex:1}}><Text style={s.cardTitle}>Administrator</Text><Text style={s.muted}>Moderate the marketplace</Text></View><Text style={role==='administrator'?s.settingOn:s.chevron}>{role==='administrator'?'✓':'›'}</Text></Pressable><Pressable style={[s.roleOption,role==='system-admin'&&s.switchOn]} onPress={()=>setRole('system-admin')}><Text style={s.roleEmoji}>⚙️</Text><View style={{flex:1}}><Text style={s.cardTitle}>System admin</Text><Text style={s.muted}>Manage the whole FixMate platform</Text></View><Text style={role==='system-admin'?s.settingOn:s.chevron}>{role==='system-admin'?'✓':'›'}</Text></Pressable></View>{role==='provider'&&<><Text style={s.sectionTitle}>Active provider profile</Text><View style={s.roleList}>{providerDirectory.map(p=><Pressable key={p.id} style={[s.roleOption,profile.name===p.name&&s.switchOn]} onPress={()=>updateProfile({name:p.name})}><View style={s.avatar}><Text style={s.avatarText}>{p.avatar}</Text></View><View style={{flex:1}}><Text style={s.cardTitle}>{p.name}</Text><Text style={s.muted}>{p.trade}</Text></View><Text style={profile.name===p.name?s.settingOn:s.chevron}>{profile.name===p.name?'✓':'›'}</Text></Pressable>)}</View></>}<Pressable style={s.menu} onPress={()=>setEditing(!editing)}><Text style={s.cardTitle}>Personal details</Text><Text style={s.chevron}>{editing?'⌃':'›'}</Text></Pressable>{editing&&<View style={s.editBox}><TextInput value={name} onChangeText={setName} placeholder="Full name" style={s.input}/><TextInput value={address} onChangeText={setAddress} placeholder="Service address" style={s.input}/><Pressable style={s.buttonSmall} onPress={save}><Text style={s.buttonText}>Save changes</Text></Pressable></View>}<SettingRow title="Favourite providers" value={`${favourites.length} saved`} /><SettingRow title="Payment methods" value="Add a payment method"/><Pressable style={s.menu} onPress={()=>updateProfile({notifications:!profile.notifications})}><Text style={s.cardTitle}>Notifications</Text><Text style={profile.notifications?s.settingOn:s.settingOff}>{profile.notifications?'On':'Off'}</Text></Pressable>{['Help & support','Terms and privacy'].map(x=><Pressable key={x} style={s.menu} onPress={()=>x==='Help & support'&&Alert.alert('FixMate support','Need a hand? Email support@fixmate.app or send us a message and our team will help you.',[{text:'OK'}])}><Text style={s.cardTitle}>{x}</Text><Text style={s.chevron}>›</Text></Pressable>)}<Pressable style={[s.outlineButton,{marginTop:20}]} onPress={logout}><Text style={s.outlineText}>Sign out</Text></Pressable></ScrollView>}
function SettingRow({title,value}:{title:string;value:string}){return <View style={s.menu}><View><Text style={s.cardTitle}>{title}</Text><Text style={s.muted}>{value}</Text></View><Text style={s.chevron}>›</Text></View>}
function ReviewModal({request,onClose}:{request:Request|null;onClose:()=>void}){const {addReview}=useApp();const [rating,setRating]=useState(0);const [comment,setComment]=useState('');if(!request)return null;const submit=()=>{if(!rating){Alert.alert('Choose a rating','Please select between 1 and 5 stars.');return;}const review:Review={id:Date.now().toString(),requestId:request.id,provider:request.provider,rating,comment,createdAt:new Date().toISOString()};addReview(review);onClose();Alert.alert('Thanks for your review','Your feedback helps the FixMate community.');};return <Modal visible transparent animationType="slide" onRequestClose={onClose}><View style={s.overlay}><View style={s.sheet}><View style={s.row}><Text style={s.modalTitle}>Rate {request.provider}</Text><Pressable onPress={onClose}><Text style={{fontSize:23}}>×</Text></Pressable></View><Text style={s.muted}>How was your {request.service.toLowerCase()} service?</Text><View style={s.stars}>{[1,2,3,4,5].map(x=><Pressable key={x} onPress={()=>setRating(x)}><Text style={[s.star,{color:x<=rating?C.gold:C.line}]}>★</Text></Pressable>)}</View><TextInput value={comment} onChangeText={setComment} placeholder="Tell other customers about your experience (optional)" placeholderTextColor={C.muted} style={[s.input,s.comment]} multiline/><Pressable style={s.button} onPress={submit}><Text style={s.buttonText}>Submit review</Text></Pressable></View></View></Modal>}
function ChatModal({message,onClose}:{message:Message|null;onClose:()=>void}){const {sendMessage,markMessageRead}=useApp();const [text,setText]=useState('');if(!message)return null;markMessageRead(message.id);const send=()=>{if(!text.trim())return;sendMessage(message.providerId,text.trim());setText('');};return <Modal visible transparent animationType="slide" onRequestClose={onClose}><KeyboardAvoidingView style={s.overlay} behavior={Platform.OS==='ios'?'padding':undefined}><View style={s.sheet}><View style={s.row}><Text style={s.modalTitle}>{message.provider}</Text><Pressable onPress={onClose}><Text style={{fontSize:23}}>×</Text></Pressable></View><View style={s.chatBubble}><Text style={s.muted}>{message.text}</Text></View><View style={s.compose}><TextInput value={text} onChangeText={setText} placeholder="Write a message..." style={s.composeInput}/><Pressable style={s.sendButton} onPress={send}><Text style={{color:C.white,fontWeight:'800'}}>Send</Text></Pressable></View></View></KeyboardAvoidingView></Modal>}
function TrackingModal({request,onClose}:{request:Request|null;onClose:()=>void}){const {updateRequest}=useApp();const [progress,setProgress]=useState(request?.status==='In progress'?62:28);useEffect(()=>{if(!request)return;const timer=setInterval(()=>setProgress(value=>{const next=Math.min(value+3,96);return next;}),1400);return()=>clearInterval(timer);},[request]);if(!request)return null;const eta=progress>75?'Arriving now':progress>45?'4 min away':'8 min away';const state=progress>75?'Almost there':progress>45?'On the way':'Heading to you';return <Modal visible transparent animationType="slide" onRequestClose={onClose}><View style={s.overlay}><View style={s.sheet}><View style={s.row}><View><Text style={s.modalTitle}>Live tracking</Text><Text style={s.muted}>{request.service} · {request.provider}</Text></View><Pressable onPress={onClose}><Text style={{fontSize:23}}>×</Text></Pressable></View><View style={s.mapPanel}><View style={s.mapRoadOne}/><View style={s.mapRoadTwo}/><Text style={s.mapLabel}>YOU</Text><Text style={[s.mapPin,{left:`${Math.max(12,Math.min(progress,88))}%`}]}>🚐</Text><Text style={s.homePin}>⌂</Text><Text style={s.mapStreet}>Long Street</Text></View><View style={s.trackSummary}><View style={s.trackAvatar}><Text style={s.avatarText}>{request.provider.split(' ').map(x=>x[0]).join('').slice(0,2)}</Text></View><View style={{flex:1,marginLeft:12}}><Text style={s.cardTitle}>{request.provider}</Text><Text style={s.muted}>{state}</Text></View><View style={{alignItems:'flex-end'}}><Text style={s.eta}>{eta}</Text><Text style={s.muted}>ETA</Text></View></View><View style={s.routeTrack}><View style={[s.routeFill,{width:`${progress}%`}]}/><View style={[s.routeDot,{left:`${Math.max(0,Math.min(progress,96))}%`}]}/></View><View style={s.trackSteps}><Text style={progress>45?s.stepActive:s.step}>Accepted</Text><Text style={progress>45?s.stepActive:s.step}>On the way</Text><Text style={progress>75?s.stepActive:s.step}>Arrived</Text></View><View style={s.trackActions}><Pressable style={s.outlineButton} onPress={()=>Alert.alert('Message provider','Open the Messages tab to continue chatting with '+request.provider+'.')}><Text style={s.outlineText}>Message</Text></Pressable><Pressable style={s.buttonSmall} onPress={()=>{updateRequest(request.id,'In progress');onClose();}}><Text style={s.buttonText}>I’m here</Text></Pressable></View></View></View></Modal>}
function QuickMatchModal({visible,onClose}:{visible:boolean;onClose:()=>void}){const {addRequest,sendMessage,profile,providerStatuses,availability,providerDirectory,serviceDirectory}=useApp();const [service,setService]=useState(serviceDirectory[0]);const [notes,setNotes]=useState('');const [stage,setStage]=useState<'form'|'searching'|'matched'|'unavailable'>('form');const terms:Record<string,string>={plumbing:'plumb',electrical:'electric',cleaning:'clean',painting:'paint',gardening:'garden',handyman:'handyman'};const term=terms[service?.id]||service?.name.toLowerCase()||'';const eligible=providerDirectory.filter(p=>providerStatuses[p.id]==='approved'&&availability[p.id]!==false);const match=eligible.find(p=>p.trade.toLowerCase().includes(term))||eligible[0];const request=()=>{if(!match){setStage('unavailable');return;}setStage('searching');setTimeout(()=>setStage('matched'),900);};const confirm=()=>{if(!match)return;const r:Request={id:Date.now().toString(),service:service.name,provider:match.name,providerId:match.id,date:'Now',time:'Arriving soon',address:profile.address||'12 Long Street, Cape Town',status:'Pending',price:match.price.replace('From ',''),customer:profile.name,customerId:profile.email,notes,createdAt:new Date().toISOString(),estimatedArrivalMinutes:8,paymentStatus:'unpaid'};addRequest(r);sendMessage(match.id,'New FixMate request: '+service.name+'. Please confirm your arrival.');setStage('form');onClose();Alert.alert('Request sent','We’re finding the best available '+service.name.toLowerCase()+' pro near you.');};return <Modal visible={visible} transparent animationType="slide" onRequestClose={onClose}><View style={s.overlay}><View style={s.sheet}>{stage==='form'?<><View style={s.row}><View><Text style={s.modalTitle}>Request help now</Text><Text style={s.muted}>Your nearest available pro will be notified.</Text></View><Pressable onPress={onClose}><Text style={{fontSize:23}}>×</Text></Pressable></View><Text style={s.modalLabel}>What do you need?</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.horizontalGap}>{serviceDirectory.map(x=><Pressable key={x.id} onPress={()=>setService(x)} style={[s.quickService,{borderColor:service.id===x.id?C.brand:C.line,backgroundColor:service.id===x.id?C.soft:C.white}]}><Text style={{fontSize:22}}>{x.icon}</Text><Text style={s.cardTitle}>{x.name}</Text></Pressable>)}</ScrollView><View style={s.address}><Text style={{fontSize:17}}>📍</Text><View style={{flex:1}}><Text style={s.locationLabel}>Pickup / service location</Text><Text style={s.locationValue}>{profile.address||'12 Long Street, Cape Town'}</Text></View><Text style={s.seeAll}>Edit</Text></View><TextInput value={notes} onChangeText={setNotes} placeholder="Add a note for your pro (optional)" placeholderTextColor={C.muted} style={[s.input,{marginTop:12}]}/><View style={s.fareBox}><View><Text style={s.muted}>Estimated starting fare</Text><Text style={s.cardTitle}>{match?.price||'Price shown after matching'}</Text></View><Text style={s.muted}>No payment until confirmed</Text></View><Pressable style={s.button} onPress={request}><Text style={s.buttonText}>Find a pro now</Text></Pressable></>:stage==='searching'?<View style={s.matchState}><Text style={s.matchEmoji}>🔎</Text><Text style={s.modalTitle}>Finding your pro</Text><Text style={s.muted}>Checking nearby FixMate professionals...</Text><View style={s.progressTrack}><View style={s.progressFill}/></View><Pressable style={s.outlineButton} onPress={()=>{setStage('form');onClose();}}><Text style={s.outlineText}>Cancel request</Text></Pressable></View>:stage==='unavailable'?<View style={s.matchState}><Text style={s.matchEmoji}>📍</Text><Text style={s.modalTitle}>No pros available</Text><Text style={s.muted}>No approved professional is online for this service right now. Try scheduling it for later.</Text><Pressable style={s.button} onPress={()=>setStage('form')}><Text style={s.buttonText}>Choose another service</Text></Pressable></View>:<View style={s.matchState}><Text style={s.matchEmoji}>🎉</Text><Text style={s.modalTitle}>Pro found nearby</Text><Text style={s.muted}>{match?.name} is available for your {service.name.toLowerCase()} request.</Text><View style={s.matchCard}><View style={s.avatar}><Text style={s.avatarText}>{match?.avatar}</Text></View><View style={{flex:1,marginLeft:12}}><Text style={s.cardTitle}>{match?.name}</Text><Text style={s.muted}>★ {match?.rating} · {match?.distance}</Text></View><Text style={s.cardPrice}>{match?.price}</Text></View><Pressable style={s.button} onPress={confirm}><Text style={s.buttonText}>Confirm request</Text></Pressable></View>}</View></View></Modal>}
function ProviderModal({provider,onClose}:{provider:Provider|null;onClose:()=>void}){const {addRequest,sendMessage,profile}=useApp();const [date,setDate]=useState('Tomorrow');const [time,setTime]=useState('09:00 - 10:00');if(!provider)return null;const book=()=>{const request:Request={id:Date.now().toString(),service:serviceName(provider.trade),provider:provider.name,providerId:provider.id,customer:profile.name,customerId:profile.email,date,time,address:profile.address||'12 Long Street, Cape Town',status:'Pending',price:provider.price.replace('From ',''),createdAt:new Date().toISOString(),estimatedArrivalMinutes:provider.distance.includes('1.')?8:15,paymentStatus:'unpaid'};addRequest(request);sendMessage(provider.id,'Hi! I’ve sent a booking request for '+date+' at '+time+'.');onClose();Alert.alert('Request sent','Your request was sent to '+provider.name+'.');};return <Modal visible animationType="slide" transparent onRequestClose={onClose}><KeyboardAvoidingView style={s.overlay} behavior={Platform.OS==='ios'?'padding':undefined}><View style={s.sheet}><View style={s.row}><View><Text style={s.modalTitle}>{provider.name}</Text><Text style={s.muted}>{provider.trade}</Text></View><Pressable onPress={()=>onClose()}><Text style={{fontSize:23}}>×</Text></Pressable></View><View style={s.modalRating}><Text style={s.rating}>★ {provider.rating}</Text><Text style={s.muted}>{provider.reviews} reviews</Text><Text style={s.verifiedText}>✓ Verified pro</Text></View><Text style={s.bio}>{provider.bio}</Text><Text style={s.modalLabel}>When would you like help?</Text><View style={s.dateRow}>{['Today','Tomorrow','Sat, 10 Aug'].map(d=><Pressable key={d} onPress={()=>setDate(d)} style={[s.date,{borderColor:date===d?C.brand:C.line,backgroundColor:date===d?C.soft:C.white}]}><Text style={{fontWeight:'700',fontSize:12}}>{d}</Text></Pressable>)}</View><View style={s.timeRow}>{['09:00 - 10:00','11:00 - 12:00','14:00 - 15:00'].map(t=><Pressable key={t} onPress={()=>setTime(t)} style={[s.time,{borderColor:time===t?C.brand:C.line,backgroundColor:time===t?C.soft:C.white}]}><Text style={{fontWeight:'600',fontSize:12}}>{t}</Text></Pressable>)}</View><View style={s.address}><Text style={{fontSize:17}}>📍</Text><View style={{flex:1}}><Text style={s.locationLabel}>Service address</Text><Text style={s.locationValue}>{profile.address||'12 Long Street, Cape Town'}</Text></View><Text style={s.seeAll}>Edit</Text></View><View style={s.summary}><Text style={s.muted}>Estimated starting price</Text><Text style={s.price}>{provider.price}</Text></View><Pressable style={s.button} onPress={book}><Text style={s.buttonText}>Request this pro</Text></Pressable></View></KeyboardAvoidingView></Modal>}
function Empty({icon,title,text}:{icon:string;title:string;text:string}){return <View style={s.empty}><Text style={{fontSize:40}}>{icon}</Text><Text style={s.cardTitle}>{title}</Text><Text style={s.muted}>{text}</Text></View>}
function LoginScreen(){const {login}=useApp();const [email,setEmail]=useState('customer@fixmate.app');const [password,setPassword]=useState('fixmate123');const [error,setError]=useState('');const submit=()=>{if(!login(email,password)){setError('Use one of the demo accounts below and the password fixmate123.');}};const demos=[['Customer','customer@fixmate.app','🏠'],['Provider','provider@fixmate.app','🛠️'],['Admin','admin@fixmate.app','🛡️'],['System admin','system@fixmate.app','⚙️']];return <SafeAreaView style={s.safe}><ScrollView contentContainerStyle={[s.content,{flexGrow:1,justifyContent:'center'}]}><View style={s.loginBrand}><Text style={s.loginLogo}>FM</Text><Text style={s.h1}>Welcome to FixMate</Text><Text style={s.subtitle}>Sign in to continue to your local services marketplace.</Text></View><View style={s.loginCard}><Text style={s.modalTitle}>Sign in</Text><TextInput value={email} onChangeText={setEmail} autoCapitalize="none" keyboardType="email-address" placeholder="Email address" placeholderTextColor={C.muted} style={[s.input,{marginTop:18}]}/><TextInput value={password} onChangeText={setPassword} secureTextEntry placeholder="Password" placeholderTextColor={C.muted} style={s.input}/>{error?<Text style={s.loginError}>{error}</Text>:null}<Pressable style={s.button} onPress={submit}><Text style={s.buttonText}>Sign in</Text></Pressable><Text style={s.loginHint}>Choose a demo role</Text>{demos.map(([label,account,icon])=><Pressable key={account} style={s.demoAccount} onPress={()=>{setEmail(account);setPassword('fixmate123');setError('')}}><Text style={{fontSize:22}}>{icon}</Text><View style={{flex:1,marginLeft:11}}><Text style={s.cardTitle}>{label}</Text><Text style={s.muted}>{account}</Text></View><Text style={s.chevron}>›</Text></Pressable>)}</View></ScrollView></SafeAreaView>}
function ComplaintModal({request,onClose}:{request:Request|null;onClose:()=>void}){const {addComplaint}=useApp();const [subject,setSubject]=useState('Service issue');const [details,setDetails]=useState('');if(!request)return null;const submit=()=>{if(!details.trim()){Alert.alert('Add more detail','Please describe the customer complaint before sending.');return;}addComplaint({id:Date.now().toString(),requestId:request.id,customer:request.customer||'Customer',subject,details:details.trim(),status:'Open',createdAt:new Date().toISOString()});setDetails('');onClose();Alert.alert('Complaint sent','The complaint has been recorded for '+(request.customer||'the customer')+'.');};return <Modal visible transparent animationType="slide" onRequestClose={onClose}><KeyboardAvoidingView style={s.overlay} behavior={Platform.OS==='ios'?'padding':undefined}><View style={s.sheet}><View style={s.row}><View><Text style={s.modalTitle}>Send complaint</Text><Text style={s.muted}>{request.service} · {request.provider}</Text></View><Pressable onPress={onClose}><Text style={{fontSize:23}}>×</Text></Pressable></View><Text style={s.modalLabel}>Subject</Text><TextInput value={subject} onChangeText={setSubject} style={s.input} placeholder="Complaint subject"/><Text style={s.modalLabel}>Details</Text><TextInput value={details} onChangeText={setDetails} multiline style={[s.input,s.comment]} placeholder="Describe what happened" placeholderTextColor={C.muted}/><Pressable style={s.button} onPress={submit}><Text style={s.buttonText}>Send complaint</Text></Pressable></View></KeyboardAvoidingView></Modal>}
function ComplaintsScreen(){const {complaints,requests}=useApp();return <ScrollView style={s.page} contentContainerStyle={s.content}><Header title="Complaints" subtitle="Review and follow up on customer issues"/>{complaints.length===0?<Empty icon="✅" title="No complaints" text="Customer complaints will appear here when an administrator records one."/>:complaints.map(c=>{const request=requests.find(r=>r.id===c.requestId);return <View style={s.adminCard} key={c.id}><View style={s.row}><View style={{flex:1}}><Text style={s.cardTitle}>{c.subject}</Text><Text style={s.muted}>{c.customer} · {request?.service||'Service request'}</Text></View><Text style={[s.pill,{color:c.status==='Open'?'#C65C5C':C.brand}]}>{c.status}</Text></View><Text style={[s.muted,{marginTop:10}]}>{c.details}</Text><Text style={[s.muted,{marginTop:8}]}>{request?.provider||'Unassigned'} · {request?.date||'Date unavailable'}</Text></View>})}</ScrollView>}
function WebSidebar({role,tab,setTab,logout}:{role:Role;tab:string;setTab:(tab:string)=>void;logout:()=>void}){const roleName=role==='system-admin'?'System admin':role==='administrator'?'Administrator':role==='provider'?'Service provider':'Customer';const items=role==='system-admin'?[['Home','Overview','◈'],['Bookings','Activity','✓'],['Profile','Settings','◎']]:role==='administrator'?[['Home','Console','▣'],['Bookings','Bookings','✓'],['Complaints','Complaints','⚠'],['Messages','Messages','✉'],['Profile','Profile','◎']]:role==='provider'?[['Home','Dashboard','⌂'],['Bookings','Jobs','✓'],['Messages','Messages','✉'],['Profile','Profile','◎']]:[['Home','Home','⌂'],['Bookings','Bookings','✓'],['Messages','Messages','✉'],['Profile','Profile','◎']];return <View style={s.sidebar}><View><View style={s.brandRow}><Text style={s.brandMark}>FM</Text><Text style={s.brandName}>FixMate</Text></View><View style={s.sidebarRole}><Text style={s.sidebarRoleLabel}>SIGNED IN AS</Text><Text style={s.sidebarRoleName}>{roleName}</Text></View><View style={s.sidebarNav}>{items.map(([key,label,icon])=><Pressable key={key} onPress={()=>setTab(key)} style={[s.sidebarItem,tab===key&&s.sidebarItemActive]}><Text style={[s.sidebarIcon,tab===key&&s.sidebarIconActive]}>{icon}</Text><Text style={[s.sidebarLabel,tab===key&&s.sidebarLabelActive]}>{label}</Text></Pressable>)}</View></View><View style={s.sidebarFooter}><Text style={s.sidebarHint}>FixMate MVP</Text><Pressable style={s.sidebarSignOut} onPress={logout}><Text style={s.sidebarSignOutText}>Sign out</Text></Pressable></View></View>}
function AppShell(){const {role,authenticated,ready,logout}=useApp();const [tab,setTab]=useState('Home');const [provider,setProvider]=useState<Provider|null>(null);const [review,setReview]=useState<Request|null>(null);const [chat,setChat]=useState<Message|null>(null);const [quickMatch,setQuickMatch]=useState(false);const [tracking,setTracking]=useState<Request|null>(null);const [complaint,setComplaint]=useState<Request|null>(null);const mobileItems=role==='administrator'?[['⌂','Home'],['✓','Bookings'],['⚠','Complaints'],['◎','Profile']]:[['⌂','Home'],['✓','Bookings'],['✉','Messages'],['◎','Profile']];if(!ready)return <SafeAreaView style={s.safe}><View style={s.loading}><Text style={s.loginLogo}>FM</Text><Text style={s.muted}>Loading FixMate…</Text></View></SafeAreaView>;if(!authenticated)return <LoginScreen/>;const screens:any={Home:role==='system-admin'?<SystemAdminDashboard/>:role==='administrator'?<AdminDashboard openComplaint={setComplaint}/>:role==='provider'?<ProviderDashboard/>:<Home openProvider={setProvider} openQuickMatch={()=>setQuickMatch(true)}/>,Bookings:<Requests onReview={setReview} onTrack={setTracking}/>,Messages:<Messages openMessage={setChat}/>,Profile:<Profile/>,Complaints:<ComplaintsScreen/>};return <SafeAreaView style={s.safe}><StatusBar barStyle="dark-content"/><View style={s.desktopLayout}>{Platform.OS==='web'&&<WebSidebar role={role} tab={tab} setTab={setTab} logout={logout}/>}<View style={{flex:1}}>{screens[tab]}</View></View>{Platform.OS!=='web'&&<View style={s.tabs}>{mobileItems.map(([icon,name])=><Pressable key={name} style={s.tab} onPress={()=>setTab(name)}><Ionicons name={tabIconName(name)} size={23} color={tab===name?C.brand:C.muted}/><Text style={[s.tabText,tab===name&&s.tabTextActive]}>{name}</Text></Pressable>)}</View>}<ProviderModal provider={provider} onClose={()=>setProvider(null)}/><ReviewModal request={review} onClose={()=>setReview(null)}/><ChatModal message={chat} onClose={()=>setChat(null)}/><QuickMatchModal visible={quickMatch} onClose={()=>setQuickMatch(false)}/><TrackingModal request={tracking} onClose={()=>setTracking(null)}/><ComplaintModal request={complaint} onClose={()=>setComplaint(null)}/></SafeAreaView>}
export default function App(){return <AppProvider><AppShell/></AppProvider>}

